from collections import Counter

class Solution:
    def countTriplets(self, nums: list[int]) -> int:
        pair_counts = Counter(x & y for x in nums for y in nums)
        res = 0
        for z in nums:
            for pair_and, cnt in pair_counts.items():
                if z & pair_and == 0:
                    res += cnt
        return res

class Solution {
public:
    int countTriplets(vector<int>& nums) {
        vector<int> pair_counts(1 << 16, 0);
        for (int x : nums) {
            for (int y : nums) {
                pair_counts[x & y]++;
            }
        }
        int res = 0;
        for (int z : nums) {
            for (int v = 0; v < (1 << 16); ++v) {
                if (pair_counts[v] && (z & v) == 0) {
                    res += pair_counts[v];
                }
            }
        }
        return res;
    }
};

class Solution {
    public int countTriplets(int[] nums) {
        int[] pairCounts = new int[1 << 16];
        for (int x : nums) {
            for (int y : nums) {
                pairCounts[x & y]++;
            }
        }
        int res = 0;
        for (int z : nums) {
            for (int v = 0; v < (1 << 16); v++) {
                if (pairCounts[v] > 0 && (z & v) == 0) {
                    res += pairCounts[v];
                }
            }
        }
        return res;
    }
}

var countTriplets = function(nums) {
    const pairCounts = new Int32Array(1 << 16);
    for (const x of nums) {
        for (const y of nums) {
            pairCounts[x & y]++;
        }
    }
    let res = 0;
    for (const z of nums) {
        for (let v = 0; v < (1 << 16); v++) {
            if (pairCounts[v] > 0 && (z & v) === 0) {
